//! Musical keys in one place (rekordbox-parity.md §8, RB-02).
//!
//! - [`KeyId`]: `pitch class + 12 · minor` (0..=23).
//! - Notations: Classic (rekordbox's spellings: `C`, `Db`, …, `Cm`, `Dbm`,
//!   …), Alphanumeric (`8A`, the default; the label avoids the "Camelot"
//!   trademark) and Open Key (`1m`, `1d`), or the tag text as is.
//! - Parsing: [`normalize_key`] is backend/utils/audio_math.py's function,
//!   bug for bug (contracts/key/normalize_key.jsonl, generated by CPython,
//!   must match line for line until the Python backend is gone);
//!   [`parse_key`] accepts that plus Open Key codes and the frontend's
//!   spellings (`C dur`, `A moll`, `A-`).
//! - [`relation`]: how a candidate key sits against a base key, for the
//!   Traffic Light and the key-compatibility filter.
//! - [`effective_key`]: the key a deck sounds in after key shift and, with
//!   keylock off, the tempo change.
//!
//! [`tables`] renders contracts/key/keys.json and the frontend module
//! generated from it (`plumdeck-key-tables`).

pub mod tables;

use plumdeck_core::compat::text::{is_py_space, py_lower, py_strip};

/// A key: `pitch class + 12 · minor`, pitch class 0 = C … 11 = B.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct KeyId(u8);

/// Major keys in rekordbox's spelling, by pitch class.
pub const CLASSIC_MAJOR: [&str; 12] = ["C", "Db", "D", "Eb", "E", "F", "F#", "G", "Ab", "A", "Bb", "B"];
/// Minor keys in rekordbox's spelling, by pitch class.
pub const CLASSIC_MINOR: [&str; 12] = ["Cm", "Dbm", "Dm", "Ebm", "Em", "Fm", "F#m", "Gm", "Abm", "Am", "Bbm", "Bm"];

/// Alphanumeric letter: `A` minor, `B` major.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Letter {
    A,
    B,
}

impl KeyId {
    pub const ALL: [KeyId; 24] = {
        let mut all = [KeyId(0); 24];
        let mut index = 0;
        while index < 24 {
            all[index] = KeyId(index as u8);
            index += 1;
        }
        all
    };

    pub fn new(pitch_class: u8, minor: bool) -> Self {
        Self(pitch_class % 12 + if minor { 12 } else { 0 })
    }

    pub fn from_index(index: u8) -> Option<Self> {
        (index < 24).then_some(Self(index))
    }

    pub fn index(self) -> u8 {
        self.0
    }

    pub fn pitch_class(self) -> u8 {
        self.0 % 12
    }

    pub fn is_minor(self) -> bool {
        self.0 >= 12
    }

    /// The key `semitones` higher (negative: lower), same mode.
    pub fn transpose(self, semitones: i32) -> Self {
        Self::new((i32::from(self.pitch_class()) + semitones).rem_euclid(12) as u8, self.is_minor())
    }

    /// The Alphanumeric number (1..=12) and letter.
    pub fn alphanumeric(self) -> (u8, Letter) {
        // Number of the major key on the same wheel position (relative major
        // for a minor key): C = 8, each fifth up adds one.
        let major = if self.is_minor() { (self.pitch_class() + 3) % 12 } else { self.pitch_class() };
        let number = ((7 * major) % 12 + 7) % 12 + 1;
        (number, if self.is_minor() { Letter::A } else { Letter::B })
    }

    /// The key at an Alphanumeric position.
    pub fn from_alphanumeric(number: u8, letter: Letter) -> Option<Self> {
        if !(1..=12).contains(&number) {
            return None;
        }
        // 7 is its own inverse modulo 12.
        let major = (7 * (i32::from(number) - 8)).rem_euclid(12) as u8;
        Some(match letter {
            Letter::B => Self::new(major, false),
            Letter::A => Self::new((major + 9) % 12, true),
        })
    }

    pub fn classic(self) -> &'static str {
        if self.is_minor() { CLASSIC_MINOR[self.pitch_class() as usize] } else { CLASSIC_MAJOR[self.pitch_class() as usize] }
    }

    /// `8A`, `12B`.
    pub fn alphanumeric_text(self) -> String {
        let (number, letter) = self.alphanumeric();
        format!("{number}{}", if letter == Letter::A { "A" } else { "B" })
    }

    /// Open Key: `((n − 8) mod 12) + 1` with `m` (minor) or `d` (major).
    pub fn open_key(self) -> String {
        let (number, letter) = self.alphanumeric();
        let open = (i32::from(number) - 8).rem_euclid(12) + 1;
        format!("{open}{}", if letter == Letter::A { "m" } else { "d" })
    }

    pub fn format(self, notation: Notation) -> String {
        match notation {
            Notation::Classic => self.classic().to_owned(),
            Notation::Alphanumeric => self.alphanumeric_text(),
            Notation::OpenKey => self.open_key(),
        }
    }
}

/// How keys are shown. The default is Alphanumeric; "as tagged" (the raw
/// text) is the caller's choice, not a rendering of a [`KeyId`].
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Notation {
    #[default]
    Alphanumeric,
    Classic,
    OpenKey,
}

/// `CAMELOT_ADJACENCY` keys of audio_math.py, in dict order.
pub const ALPHANUMERIC_CODES: [&str; 24] = [
    "1A", "1B", "2A", "2B", "3A", "3B", "4A", "4B", "5A", "5B", "6A", "6B", "7A", "7B", "8A", "8B", "9A", "9B",
    "10A", "10B", "11A", "11B", "12A", "12B",
];

