/// `re.fullmatch(word, text, re.IGNORECASE)` for an ASCII word. With
/// IGNORECASE Python also matches `ı` (U+0131) and `İ` (U+0130) to `i`.
fn matches_word_ignorecase(text: &str, word: &str) -> bool {
    let mut chars = text.chars();
    for expected in word.chars() {
        let Some(c) = chars.next() else { return false };
        let same = c.eq_ignore_ascii_case(&expected) || (expected == 'i' && matches!(c, '\u{131}' | '\u{130}'));
        if !same {
            return false;
        }
    }
    chars.next().is_none()
}

/// audio_math.py `normalize_key`: any spelling it accepts (`'F minor'`,
/// `'Fm'`, `'4a'`, `'D♯ Minor'`) to its Alphanumeric code, or `None`.
pub fn normalize_key(key: Option<&str>) -> Option<&'static str> {
    let key = key?;
    let stripped = py_strip(key);
    if stripped.is_empty() {
        return None;
    }
    let key = stripped.replace('♯', "#").replace('♭', "b");
    // `key_str.upper() in CAMELOT_ADJACENCY`: only ASCII letters can
    // uppercase into a code.
    let upper = key.to_ascii_uppercase();
    if let Some(code) = ALPHANUMERIC_CODES.iter().find(|code| **code == upper) {
        return Some(code);
    }
    // ([A-Ga-g])([#b]?)\s*(major|minor|maj|min|m)? under IGNORECASE.
    let mut rest = key.as_str();
    let note = rest.chars().next().filter(|c| matches!(c.to_ascii_lowercase(), 'a'..='g'))?;
    rest = &rest[note.len_utf8()..];
    let accidental = match rest.chars().next() {
        Some(c @ ('#' | 'b' | 'B')) => {
            rest = &rest[1..];
            c.to_ascii_lowercase().to_string()
        }
        _ => String::new(),
    };
    rest = rest.trim_start_matches(is_py_space);
    let scale = if rest.is_empty() {
        None
    } else if ["major", "minor", "maj", "min", "m"].iter().any(|word| matches_word_ignorecase(rest, word)) {
        Some(rest)
    } else {
        return None;
    };
    let minor = scale.is_some_and(|scale| scale != "M" && ["minor", "min", "m"].contains(&py_lower(scale).as_str()));
    let name = format!("{}{accidental} {}", note.to_ascii_uppercase(), if minor { "Minor" } else { "Major" });
    KEY_TO_CAMELOT.iter().find(|(spelling, _)| *spelling == name).map(|(_, code)| *code)
}

/// A code from [`ALPHANUMERIC_CODES`] as a key.
pub fn from_code(code: &str) -> Option<KeyId> {
    let (number, letter) = code.split_at(code.len().checked_sub(1)?);
    let letter = match letter {
        "A" | "a" => Letter::A,
        "B" | "b" => Letter::B,
        _ => return None,
    };
    KeyId::from_alphanumeric(number.parse().ok()?, letter)
}

const NOTE_PITCH: [(char, u8); 7] = [('c', 0), ('d', 2), ('e', 4), ('f', 5), ('g', 7), ('a', 9), ('b', 11)];

/// The frontend's extra spellings (musical-key.ts): `dur`/`ma` major,
/// `moll`/`-` minor, any whitespace.
fn parse_frontend(text: &str) -> Option<KeyId> {
    let text = text.trim().replace('♯', "#").replace('♭', "b");
    let mut chars = text.chars();
    let note = chars.next()?.to_ascii_lowercase();
    let mut pitch = i32::from(NOTE_PITCH.iter().find(|(n, _)| *n == note)?.1);
    let mut rest = chars.as_str().trim_start();
    if let Some(after) = rest.strip_prefix('#') {
        pitch += 1;
        rest = after;
    } else if let Some(after) = rest.strip_prefix('b').or_else(|| rest.strip_prefix('B')) {
        // `Bb` is B-flat; a lone `b` after the note is the flat sign too.
        pitch -= 1;
        rest = after;
    }
    let quality = rest.trim().to_ascii_lowercase();
    let minor = match quality.as_str() {
        "" | "maj" | "major" | "ma" | "dur" => false,
        "m" | "min" | "minor" | "moll" | "-" => true,
        _ => return None,
    };
    Some(KeyId::new(pitch.rem_euclid(12) as u8, minor))
}

/// Open Key codes: `1d`..`12d` (major), `1m`..`12m` (minor).
fn parse_open_key(text: &str) -> Option<KeyId> {
    let text = text.trim();
    let (number, letter) = text.split_at(text.len().checked_sub(1)?);
    let minor = match letter {
        "m" | "M" => true,
        "d" | "D" => false,
        _ => return None,
    };
    let open: i32 = number.trim().parse().ok()?;
    if !(1..=12).contains(&open) {
        return None;
    }
    let alphanumeric = ((open - 1 + 7) % 12 + 1) as u8;
    KeyId::from_alphanumeric(alphanumeric, if minor { Letter::A } else { Letter::B })
}

/// Any accepted spelling: what [`normalize_key`] reads, then Open Key and
/// the frontend's spellings. `None` for anything else.
pub fn parse_key(text: &str) -> Option<KeyId> {
    normalize_key(Some(text)).and_then(from_code).or_else(|| parse_open_key(text)).or_else(|| parse_frontend(text))
}

/// How a candidate key relates to a base key, from the base's point of
/// view (rekordbox-parity.md §8).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Relation {
    /// The same key.
    Same,
    /// Same letter, number ±1 (a fifth up or down).
    Adjacent,
    /// Same number, other letter (relative major/minor).
    Relative,
    /// Other letter, number +1 from minor or −1 from major (8A → 9B, 8B → 7A).
    Diagonal,
    /// Same letter, number +2 (the "energy boost" step).
    Plus2,
    /// Same mode, a semitone up or down.
    Semitone,
    Other,
}

impl Relation {
    pub const ALL: [Relation; 7] = [
        Relation::Same,
        Relation::Adjacent,
        Relation::Relative,
        Relation::Diagonal,
        Relation::Plus2,
        Relation::Semitone,
        Relation::Other,
    ];

    pub fn name(self) -> &'static str {
        match self {
            Relation::Same => "same",
            Relation::Adjacent => "adjacent",
            Relation::Relative => "relative",
            Relation::Diagonal => "diagonal",
            Relation::Plus2 => "plus2",
            Relation::Semitone => "semitone",
            Relation::Other => "other",
        }
    }

    /// Traffic Light level: 1 (green: same, adjacent, relative), 2 (yellow:
    /// diagonal, +2), none otherwise.
    pub fn traffic_light(self) -> Option<u8> {
        match self {
            Relation::Same | Relation::Adjacent | Relation::Relative => Some(1),
            Relation::Diagonal | Relation::Plus2 => Some(2),
            _ => None,
        }
    }

    /// Kept by the key-compatibility filter (same, adjacent, relative).
    pub fn is_compatible(self) -> bool {
        self.traffic_light() == Some(1)
    }
}

/// [`Relation`] of `candidate` against `base`.
pub fn relation(base: KeyId, candidate: KeyId) -> Relation {
    let (bn, bl) = base.alphanumeric();
    let (cn, cl) = candidate.alphanumeric();
    let step = (i32::from(cn) - i32::from(bn)).rem_euclid(12);
    if base == candidate {
        Relation::Same
    } else if bl == cl && (step == 1 || step == 11) {
        Relation::Adjacent
    } else if bl != cl && step == 0 {
        Relation::Relative
    } else if (bl == Letter::A && cl == Letter::B && step == 1) || (bl == Letter::B && cl == Letter::A && step == 11) {
        Relation::Diagonal
    } else if bl == cl && step == 2 {
        Relation::Plus2
    } else if base.is_minor() == candidate.is_minor()
        && matches!((i32::from(candidate.pitch_class()) - i32::from(base.pitch_class())).rem_euclid(12), 1 | 11)
    {
        Relation::Semitone
    } else {
        Relation::Other
    }
}

/// The key a deck plays in.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct EffectiveKey {
    pub key: KeyId,
    /// The total shift in semitones (key shift plus the tempo's pitch change
    /// when keylock is off), before rounding.
    pub semitones: f64,
    /// More than 30 cents off the semitone grid: shown with "≈".
    pub approximate: bool,
}

/// `semitones = key_shift + (keylock ? 0 : 12·log2(tempo_ratio))`, the key
/// rotated by the rounded shift. A ratio that is not positive and finite
/// counts as 1.
pub fn effective_key(base: KeyId, key_shift: f64, tempo_ratio: f64, keylock: bool) -> EffectiveKey {
    let shift = if key_shift.is_finite() { key_shift } else { 0.0 };
    let tempo = if keylock || !(tempo_ratio > 0.0 && tempo_ratio.is_finite()) { 0.0 } else { 12.0 * tempo_ratio.log2() };
    let semitones = shift + tempo;
    let rounded = semitones.round();
    EffectiveKey {
        key: base.transpose(rounded as i32),
        semitones,
        approximate: ((semitones - rounded) * 100.0).abs() > 30.0,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn notations_follow_the_spec() {
        let am = KeyId::new(9, true);
        assert_eq!((am.classic(), am.alphanumeric_text(), am.open_key()), ("Am", "8A".into(), "1m".into()));
        let c = KeyId::new(0, false);
        assert_eq!((c.alphanumeric_text(), c.open_key()), ("8B".into(), "1d".into()));
        for (key, code) in [(KeyId::new(8, true), "1A"), (KeyId::new(11, false), "1B"), (KeyId::new(3, true), "2A"), (KeyId::new(6, false), "2B")] {
            assert_eq!(key.alphanumeric_text(), code);
            assert_eq!(from_code(code), Some(key));
        }
        for key in KeyId::ALL {
            let (number, letter) = key.alphanumeric();
            assert_eq!(KeyId::from_alphanumeric(number, letter), Some(key));
            assert_eq!(parse_key(&key.open_key()), Some(key), "{}", key.open_key());
            assert_eq!(parse_key(key.classic()), Some(key), "{}", key.classic());
            assert_eq!(parse_key(&key.alphanumeric_text()), Some(key));
        }
    }

    #[test]
    fn parse_accepts_the_listed_spellings() {
        let am = Some(KeyId::new(9, true));
        for text in ["A minor", "Am", "a min", "8A", "1m", " 8a "] {
            assert_eq!(parse_key(text), am, "{text}");
        }
        assert_eq!(parse_key("G#m"), Some(KeyId::new(8, true)));
        assert_eq!(parse_key("A#m"), Some(KeyId::new(10, true)));
        assert_eq!(KeyId::new(10, true).classic(), "Bbm");
        assert_eq!(parse_key("D♭"), Some(KeyId::new(1, false)));
        assert_eq!(parse_key("C dur"), Some(KeyId::new(0, false)));
        assert_eq!(parse_key("A moll"), am);
        for text in ["", "H", "13A", "0m", "C7", "minor"] {
            assert_eq!(parse_key(text), None, "{text}");
        }
    }

    #[test]
    fn normalize_key_matches_python_vectors() {
        let text = include_str!("../../../../contracts/key/normalize_key.jsonl");
        let mut accepted = 0;
        for line in text.lines() {
            let row: serde_json::Value = serde_json::from_str(line).unwrap();
            let input = row["input"].as_str().unwrap();
            let expected = row["camelot"].as_str();
            assert_eq!(normalize_key(Some(input)), expected, "{line}");
            if let Some(code) = expected {
                // The wider parser agrees wherever Python accepts the text.
                assert_eq!(parse_key(input), from_code(code), "{line}");
                accepted += 1;
            }
        }
        assert!(accepted > 2000);
        assert_eq!(normalize_key(None), None);
    }

    #[test]
    fn relations_and_traffic_light() {
        let key = |code: &str| from_code(code).unwrap();
        let cases = [
            ("8A", "8A", Relation::Same),
            ("8A", "9A", Relation::Adjacent),
            ("8A", "7A", Relation::Adjacent),
            ("12B", "1B", Relation::Adjacent),
            ("8A", "8B", Relation::Relative),
            ("8A", "9B", Relation::Diagonal),
            ("8B", "7A", Relation::Diagonal),
            ("8A", "7B", Relation::Other),
            ("8A", "10A", Relation::Plus2),
            ("11B", "1B", Relation::Plus2),
            ("8A", "3A", Relation::Semitone),
            ("8A", "1A", Relation::Semitone),
            ("8A", "2B", Relation::Other),
        ];
        for (base, candidate, expected) in cases {
            assert_eq!(relation(key(base), key(candidate)), expected, "{base} → {candidate}");
        }
        assert_eq!(Relation::Diagonal.traffic_light(), Some(2));
        assert!(Relation::Relative.is_compatible() && !Relation::Plus2.is_compatible());
    }

    #[test]
    fn effective_key_rounds_and_flags_cents() {
        let am = KeyId::new(9, true);
        assert_eq!(effective_key(am, 2.0, 1.0, false).key, KeyId::new(11, true));
        let up = effective_key(am, 0.0, 1.06, false);
        assert_eq!(up.key, KeyId::new(10, true));
        assert!(!up.approximate, "1.06 is about +1.01 semitones");
        assert!(effective_key(am, 0.0, 1.08, false).approximate);
        assert_eq!(effective_key(am, -1.0, 1.08, true).key, KeyId::new(8, true));
        assert_eq!(effective_key(am, f64::NAN, 0.0, false).key, am);
    }
}
